B.Wj=new A.hT("holtak_szeme","Holtak szeme",B.jQ,1,1,null,"A karakter k\xfcl\xf6n\xf6sen \xe9rz\xe9keny a m\xe1svil\xe1gi entit\xe1sok, illetve az evil\xe1g hat\xe1r\xe1n sodr\xf3d\xf3 l\xe9nyek keltette benyom\xe1sokra.","20 ynevi l\xe1b sugar\xfa g\xf6mbben m\xe1gia vagy pszi haszn\xe1lat n\xe9lk\xfcl k\xe9pes \xe9rz\xe9kelni holt lelkek, k\xeds\xe9rtetek, lid\xe9rcek \xe9s m\xe1s t\xfalvil\xe1gi l\xe9nyek jelenl\xe9t\xe9t. Meg\xe9rzi, ha egy ter\xfcleten 1 napn\xe1l nem r\xe9gebben egy \xe9rtelmes \xe9l\u0151l\xe9ny lelte hal\xe1l\xe1t.",null)
B.Wg=new A.hT("sugallat","Sugallat",B.jQ,1,1,null,"A karakternek bizonyos id\u0151k\xf6z\xf6nk\xe9nt megmagyar\xe1zhatatlan meg\xe9rz\xe9sei, l\xe1tom\xe1sai, hallucin\xe1ci\xf3i t\xe1madnak.","\xdagy \xe9rzi, mintha kor\xe1bban meg\xe9lte volna m\xe1r az adott szitu\xe1ci\xf3t. Meg\xe9rz\xe9sei n\xe9ha \xe9letment\u0151ek lehetnek. A KM dobhat \xc9rz\xe9kel\xe9s- vagy Gyorsas\xe1gpr\xf3b\xe1t, hogy a karakter k\xe9pes-e id\u0151ben reag\xe1lni.",null)
